def main() -> int:
    repo = Path(sys.argv[1]) if len(sys.argv) > 1 else Path(__file__).resolve().parent
    repo = repo.resolve()
    if not (repo / ".git").exists():
        print(f"[apply] ERROR: {repo} is not a git repository.", file=sys.stderr)
        return 1

    patch_bytes = base64.b64decode("".join(PATCH_B64))
    actual = hashlib.sha256(patch_bytes).hexdigest()
    if actual != EXPECTED_SHA256:
        print(f"[apply] ERROR: checksum mismatch: {actual} != {EXPECTED_SHA256}", file=sys.stderr)
        return 1

    patch_path = repo / "nstl_round6.patch"
    patch_path.write_bytes(patch_bytes)
    print(f"[apply] patch written: {patch_path} ({len(patch_bytes)} bytes, sha256 ok)")

    try:
        subprocess.run(["git", "apply", "--check", str(patch_path)],
                       cwd=str(repo), check=True)
        subprocess.run(["git", "apply", str(patch_path)], cwd=str(repo), check=True)
    except FileNotFoundError:
        res = subprocess.run(["patch", "-p1", "--forward", "-i", str(patch_path)],
                             cwd=str(repo))
        if res.returncode != 0:
            print("[apply] ERROR: `patch -p1` failed.", file=sys.stderr)
            return 1
    except subprocess.CalledProcessError as exc:
        print(f"[apply] ERROR: git apply --check failed (already applied or "
              f"unexpected base commit?): {exc}", file=sys.stderr)
        return 1

    print("[apply] OK — round-6 changes applied. Run: python scripts/check_static.py && python -m pytest tests -q")
    return 0


if __name__ == "__main__":
    sys.exit(main())
